func run(drain bool) int32 {
	var conns atomic.Int32
	srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		io.WriteString(w, strings.Repeat("x", 5_000_000))
	}))
	srv.Config.ConnState = func(_ net.Conn, s http.ConnState) {
		if s == http.StateNew {
			conns.Add(1)
		}
	}
	srv.Start()
	defer srv.Close()
	client := &http.Client{Transport: &http.Transport{}}
	for i := 0; i < 5; i++ {
		resp, _ := client.Get(srv.URL)
		if drain {
			io.Copy(io.Discard, resp.Body)
		}
		resp.Body.Close()
	}
	return conns.Load()
}

func main() {
	fmt.Println("no drain:", run(false), "connections")
	fmt.Println("drain:   ", run(true), "connection")
}

